const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
const workspace=$('#workspace'),admin=$('#admin'),feed=$('#feed'),feedInner=$('#feedInner');
const conversations=new Map(),tasks=[],resultImages=new Map(),resultImageMeta=new Map();
const TASK_STORAGE_KEY='qijing-ai-generation-tasks-v2';
