const PROMPT_STORAGE_KEY='qijing-ai-prompt-config-v1';
const DEFAULT_PROMPTS={
  round0:'解析操作类型、基础图、商品图、点选位置、文字指令、真实尺寸、点选/文字冲突状态和落点纠错状态。识别支撑面、空间纵深、透视、光线、遮挡物和安全摆放区域。本轮只输出结构化分析，不生成图片，不重新设计房间。',
  round1:'你是一个真实家居空间图片编辑模型。根据基础房间图片、家具商品参考图、结构化任务和用户要求完成第一次图片编辑。保持基础图片的空间结构、拍摄角度、构图和透视关系；仅修改指定对象或区域；严格参考商品外形、颜色、材质、结构和关键设计细节。ADD 不删除原有家具，REPLACE 只删除并替换用户指定的家具，不得删除无关物品；原家具上方或附近的独立小物品，在物理关系合理时应自然保留。根据透视和尺寸调整大小与角度，使商品与支撑面自然接触，并保持正确前后遮挡，禁止悬空、穿模或错误覆盖。除编辑区域外，保持原房间的墙面/地面纹理、曝光、颗粒、对比度、饱和度和色温，不得美化、磨皮、柔光、降噪或全局重新调色。输出真实室内摄影预览，不要重新设计整个房间。优先级：完成用户要求 > 商品保真 > 空间保真 > 视觉自然。',
  round2:'基于 Round 1 中间图做一次综合修正。必须以 Image 3 原始基础房间图为背景保真基准：编辑区域之外尽量逐像素保持原房间外观，保留原墙面与地面纹理、原曝光、原图像颗粒/噪声、原对比度、原饱和度和原色温；禁止背景磨皮、柔化、降噪、美化，禁止全局柔光、全局调色、全局改变对比度/饱和度/色温。只允许在新增或替换家具的边缘、接触面和投影范围内进行必要的局部光影融合。\n同时检查并修正尺寸比例、透视、接地、悬空、前后遮挡、物体穿模、墙体穿透、接触阴影、局部投影和边缘融合。建立正确的前后深度关系：已有前景物体应自然遮挡新家具，新家具只在空间关系正确时遮挡背景物体，任何家具、墙面和小物品都不得互相穿过。REPLACE 只删除被明确替换的家具；无关家具和独立小物品必须保留。原家具上方或附近的小物品若可合理存在，应原位保留或自然落在替换家具的对应支撑面上，不得无故消失。保持商品外观、目标位置、房间结构、机位、构图和所有未编辑区域不变。不得新增家具或装饰，不得重新设计商品或房间。输出应像商品真实存在于原始场景中的摄影照片，而不是拼贴图。',
  round3:'比较基础房间图、商品参考图、用户要求、结构化任务和 Round 2 结果。检查商品一致性、位置、比例、透视、接地、阴影、穿模、遮挡、悬空、应保留物品丢失和背景漂移。明显失败时输出 FAIL 和局部纠错要求；不要因轻微压缩或审美差异判定失败。'
};
const PROMPT_LABELS={round0:'Round 0 · 需求解析',round1:'Round 1 · 基础生成',round2:'Round 2 · 综合修正',round3:'Round 3 · 质量检查'};
function defaultPromptConfig(){return{prompt_version:'prompt-v1',last_updated_at:'2026-10-07T12:00:00.000Z',prompts:{...DEFAULT_PROMPTS}}}
function loadPromptConfig(){try{const saved=JSON.parse(localStorage.getItem(PROMPT_STORAGE_KEY)||'null');if(!saved||!saved.prompts)return defaultPromptConfig();const prompts={};for(const key of Object.keys(DEFAULT_PROMPTS))prompts[key]=typeof saved.prompts[key]==='string'&&saved.prompts[key].trim()?saved.prompts[key]:DEFAULT_PROMPTS[key];return{prompt_version:saved.prompt_version||'prompt-v1',last_updated_at:saved.last_updated_at||defaultPromptConfig().last_updated_at,prompts}}catch{return defaultPromptConfig()}}
function copyPromptConfig(config=promptConfig){return{prompt_version:config.prompt_version,last_updated_at:config.last_updated_at,prompts:{...config.prompts}}}
let promptConfig=loadPromptConfig();
function loadDeletedConversationIds(){try{return new Set(JSON.parse(localStorage.getItem(DELETED_CONVERSATIONS_KEY)||'[]'))}catch{return new Set()}}
const deletedConversationIds=loadDeletedConversationIds();
let currentChatId='chat-chair',reference=null,target={x:20,y:67,x_ratio:.2,y_ratio:.67},operation='ADD';
let productSrc='assets/caramel-chair.png',roomSrc='assets/living-room.png',roomImageMeta={original_width:1586,original_height:992,aspect_ratio:1586/992,source_kind:'bundled-original'},version=0,sceneId='scene-default',baseImageId='image-original-default',toastTimer,taskCounter=25001;

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(prefix){return`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`}
function askChoice(message,choices){return new Promise(resolve=>{const dialog=$('#choiceDialog'),actions=$('#choiceActions');$('#choiceMessage').textContent=message;actions.innerHTML='';choices.forEach((choice,index)=>{const button=document.createElement('button');button.className='choice-action'+(index===0?' primary':'');button.textContent=choice.label;button.onclick=()=>{dialog.classList.remove('show');resolve(choice.value)};actions.appendChild(button)});dialog.classList.add('show')})}
function switchView(view){workspace.classList.toggle('off',view!=='workspace');admin.classList.toggle('off',view!=='admin');$$('.viewbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#adminShortcut').textContent=view==='admin'?'⌂':'⚙';if(view==='admin'){loadTaskHistory();renderPromptManager();renderTaskRows();if(tasks[0])renderPipeline(tasks[0])}}
$$('.viewbtn').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
$('#adminShortcut').onclick=()=>switchView(admin.classList.contains('off')?'admin':'workspace');

function setOperation(op,quiet=false){operation=op;$$('[data-op]').forEach(b=>b.classList.toggle('active',b.dataset.op===op));if(!quiet){snapshotCurrent();toast(op==='ADD'?'添加模式：点选家具底部中心':'替换模式：点选要替换物体的中心或接地点')}}
$$('[data-op]').forEach(b=>b.onclick=()=>setOperation(b.dataset.op));
function getDimensions(){const read=id=>{const n=parseFloat($(id).value);return Number.isFinite(n)&&n>0?n:null};return{length:read('#dimLength'),width:read('#dimWidth'),height:read('#dimHeight')}}
function updateTargetUI(){if(target){$('#targetText').textContent=`点选位置 ${target.x}%, ${target.y}%`;$('#targetCard').innerHTML=`已点选目标位置<br><strong>X ${target.x}% · Y ${target.y}%</strong>`}else{$('#targetText').textContent='尚未点选位置';$('#targetCard').innerHTML='尚未点选目标位置<br><strong>请直接单击对话中的图片</strong>'}}
function updateScaleHint(){const d=getDimensions();$('#scaleHint').textContent=d.length||d.width||d.height?'已输入真实尺寸；空间分析会把厘米尺寸与地面纵深、透视比例共同送入生成模型。':'未填写时，空间分析会根据家具类别、地面纵深和房间参照物估算合理比例。'}
['#dimLength','#dimWidth','#dimHeight'].forEach(id=>$(id).addEventListener('input',updateScaleHint));
function targetFromRatios(xRatio,yRatio){const x_ratio=Math.min(1,Math.max(0,xRatio)),y_ratio=Math.min(1,Math.max(0,yRatio));return{x:Math.round(x_ratio*100),y:Math.round(y_ratio*100),x_ratio,y_ratio}}
function setPoint(e){const stage=e.currentTarget,img=$('.room',stage),r=(img||stage).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return toast('请在完整图片范围内点选位置');target=targetFromRatios((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);let point=$('.point',stage);if(!point){point=document.createElement('span');point.className='point';stage.appendChild(point)}point.style.left=target.x_ratio*100+'%';point.style.top=target.y_ratio*100+'%';updateTargetUI();toast('落点已按原图归一化坐标记录')}

function setReference(v){reference=v;const src=resultImages.get(v)||roomSrc;$('#replyTitle').textContent='正在引用效果图 '+v;$('#replyBar img').src=src;$('#replyBar').classList.add('show');$('#prompt').focus();toast('下一轮将以 '+v+' 作为主编辑图像')}
$('#replyClose').onclick=()=>{reference=null;$('#replyBar').classList.remove('show')};
$('#clearPoint').onclick=()=>{$$('.point',feedInner).forEach(p=>p.remove());target=null;updateTargetUI();toast('已清除点选位置')};

function bindInteractive(root=document){
  $$('.selectable-image',root).forEach(el=>el.onclick=setPoint);
  $$('.quote-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();setReference(b.dataset.version)});
  $$('.regen-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();$('#prompt').value='基于相同素材重新生成，重点修正空间比例、透视、接地与光影融合';sendMessage()});
  $$('.retry-task-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();retryFailedTask(b.dataset.taskId)});
  $$('.download-btn',root).forEach(b=>b.onclick=e=>{e.stopPropagation();downloadResult(b.dataset.src)});
}
function addUser(text,baseLabel,context={}){const m=document.createElement('div');m.className='message user';const bubble=document.createElement('div');bubble.className='bubble';if(baseLabel&&baseLabel!=='Original'){const q=document.createElement('div');q.className='quote-inline';q.innerHTML=`<img src="${escapeHTML(context.baseImageSource||resultImages.get(baseLabel)||roomSrc)}" alt="引用图"><div><strong>引用效果图 ${escapeHTML(baseLabel)}</strong><span>作为本轮主编辑图</span></div>`;bubble.appendChild(q)}bubble.append(document.createTextNode(((context.operation||operation)==='ADD'?'添加':'替换')+'：'+text));m.innerHTML='<div class="msgavatar">你</div>';m.prepend(bubble);feedInner.appendChild(m)}
function addAI(text){const m=document.createElement('div');m.className='message';m.innerHTML='<div class="msgavatar">AI</div>';const b=document.createElement('div');b.className='bubble';b.textContent=text;m.appendChild(b);feedInner.appendChild(m)}
function addProgress(taskId){const box=document.createElement('div');box.className='round-status';box.dataset.taskId=taskId;box.innerHTML=['正在理解需求','正在生成基础效果','正在优化空间与光影','正在检查结果','完成'].map((n,i)=>`<div class="round-row ${i===0?'running':''}"><span class="round-dot"></span><strong>阶段 ${i+1}</strong><span>${n}</span></div>`).join('');feedInner.appendChild(box);return box}
function updateProgress(box,index,state='running'){if(!box)return;const rows=$$('.round-row',box);rows.forEach((row,i)=>{if(i<index)row.className='round-row done';else if(i===index)row.className=`round-row ${state}`;else row.className='round-row'});if(box.isConnected)feed.scrollTop=feed.scrollHeight}
function finishProgress(box,rounds,ok){if(!box)return;const rows=$$('.round-row',box);rows.forEach(r=>r.className='round-row');if(ok)rows.forEach(r=>r.classList.add('done'));else{const failedAt=Math.min(rows.length-2,Math.max(0,rounds.length));rows.forEach((r,i)=>{if(i<failedAt)r.classList.add('done')});rows[failedAt]?.classList.add('failed')}}

function resultCard(result,base,v,dimensions={}){const qc=result.qc||{},status=qc.incomplete?'QC 待确认':qc.pass?'QC PASS':'QC WARN',size=Object.values(dimensions).some(Boolean)?Object.values(dimensions).map(x=>x||'自动').join('×')+'cm':'模型自动估算',wrap=document.createElement('div');wrap.className='asset-message';wrap.innerHTML=`<div class="image-card"><div class="image-stage selectable-image effect-stage" data-version="${v}"><img class="room" src="${escapeHTML(result.resultUrl)}" alt="场景编辑效果图 ${v}"></div><div class="image-caption"><div class="image-caption-text"><strong>效果图 ${v}</strong><span>基于 ${escapeHTML(base)} · ${size} · ${status} · ${result.attempts||1} 次生成</span></div><div class="image-actions"><button class="image-action primary quote-btn" data-version="${v}">引用这张图</button><button class="image-action download-btn" data-src="${escapeHTML(result.resultUrl)}">下载</button><button class="image-action regen-btn">重新生成</button></div></div></div>`;return wrap}
function aiMessage(text,retryTaskId=''){const m=document.createElement('div');m.className='message';m.innerHTML='<div class="msgavatar">AI</div>';const b=document.createElement('div');b.className='bubble';const p=document.createElement('div');p.textContent=text;b.appendChild(p);if(retryTaskId){const button=document.createElement('button');button.className='retry-task-btn';button.dataset.taskId=retryTaskId;button.textContent='重新生成';b.appendChild(button)}m.appendChild(b);return m}
function mutationForConversation(conversationId){if(conversationId===currentChatId)return{active:true,root:feedInner,state:null};const state=conversations.get(conversationId);if(!state)throw new Error('任务所属历史对话不存在');const root=document.createElement('div');root.innerHTML=state.feedHTML||'';return{active:false,root,state}}
function commitConversationMutation(task,mutation){if(mutation.active){bindInteractive(feedInner);refreshHeader();snapshotCurrent()}else{mutation.state.feedHTML=mutation.root.innerHTML;conversations.set(task.conversation_id,mutation.state);const button=$(`.session[data-chat="${task.conversation_id}"]`),badge=button&&$('.session-meta span:last-child',button);if(badge)badge.textContent=(mutation.state.version||0)+' 张图';persistConversations()}}
function outputMetaFromTask(task){const round=[...(task.rounds||[])].reverse().find(item=>item.imageUrl&&item.output_image_meta);return round?.output_image_meta||task.context?.baseImageMeta||null}
function deliverTaskSuccess(task,result){const mutation=mutationForConversation(task.conversation_id),state=mutation.active?null:mutation.state,nextVersion=(mutation.active?version:(state.version||0))+1,v='V'+nextVersion,progress=$(`.round-status[data-task-id="${task.id}"]`,mutation.root);finishProgress(progress,task.rounds,true);mutation.root.appendChild(resultCard(result,task.base,v,task.context.dimensions));const warnings=(result.qc?.issues||[]).join('、'),message=result.qc?.incomplete?`已完成 ${v}。Round 2 效果图已正常生成并保留；质量检查服务暂时不可用，因此本图标记为“QC 待确认”，仍可查看、引用和下载。`:result.qc?.pass?`已完成 ${v}。这是服务端场景编辑生成的单张融合图，不含前端商品叠加层；空间、透视、接地、光影和背景保护已通过视觉检查。`:`已完成 ${v}，但质量检查仍提示：${warnings||'建议补充更准确的尺寸或位置'}。系统已按规则自动重试一次。`;mutation.root.appendChild(aiMessage(message));const resultId=`${task.id}:result:${v}`,outputMeta=outputMetaFromTask(task);if(mutation.active){version=nextVersion;resultImages.set(v,result.resultUrl);if(outputMeta)resultImageMeta.set(v,outputMeta);roomSrc=result.resultUrl;roomImageMeta=outputMeta||roomImageMeta;baseImageId=resultId}else{state.version=nextVersion;state.roomSrc=result.resultUrl;state.roomImageMeta=outputMeta||state.roomImageMeta;state.baseImageId=resultId;state.resultImages={...(state.resultImages||{}),[v]:result.resultUrl};state.resultImageMeta={...(state.resultImageMeta||{}),[v]:outputMeta};state.meta=`已自动保存 · ${$$('.message',mutation.root).length} 条消息 · ${$$('.effect-stage',mutation.root).length} 张真实生成图`}commitConversationMutation(task,mutation);return v}
function deliverTaskFailure(task,errorText){const mutation=mutationForConversation(task.conversation_id),progress=$(`.round-status[data-task-id="${task.id}"]`,mutation.root);finishProgress(progress,task.rounds,false);mutation.root.appendChild(aiMessage('本次没有生成拼贴兜底图。场景编辑服务失败：'+errorText+'。已保留本轮素材与指令。',task.id));commitConversationMutation(task,mutation)}
async function downloadResult(src){if(!src)return;try{const r=await fetch(src);if(!r.ok)throw new Error('download');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='栖境AI-效果图.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{window.open(src,'_blank')}}

function persistTasks(){try{const compact=tasks.slice(0,20).map(task=>{const copy={...task,context:task.context?{...task.context}:null};if(copy.context){delete copy.context.baseImageSource;delete copy.context.productImageSource}return copy});localStorage.setItem(TASK_STORAGE_KEY,JSON.stringify(compact))}catch(err){console.warn('任务记录保存失败',err)}}
function loadTaskHistory(){try{const saved=JSON.parse(localStorage.getItem(TASK_STORAGE_KEY)||'[]');if(!Array.isArray(saved)||!saved.length)return;const live=new Map(tasks.map(t=>[t.id,t]));for(const item of saved)if(!live.has(item.id))live.set(item.id,item);tasks.splice(0,tasks.length,...[...live.values()].sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).slice(0,20));const nums=tasks.map(t=>Number(String(t.id).replace(/\D/g,''))).filter(Number.isFinite);if(nums.length)taskCounter=Math.max(taskCounter,Math.max(...nums)+1)}catch(err){console.warn('任务记录读取失败',err)}}
function captureTaskContext(text){const baseLabel=reference||'Original';return{conversationId:currentChatId,sceneId,baseImageId:reference?`${currentChatId}:${reference}`:baseImageId,baseLabel,baseImageSource:reference?(resultImages.get(reference)||roomSrc):roomSrc,baseImageMeta:reference?(resultImageMeta.get(reference)||roomImageMeta):roomImageMeta,productImageSource:productSrc,operation,target:{...target},dimensions:getDimensions(),instruction:text,title:$('.chathead-title').textContent||deriveTitle(text)}}
function newTask(context,retryOf=''){const id='TASK-'+taskCounter++,prompt_snapshot=copyPromptConfig(),task={id,task_id:id,conversation_id:context.conversationId,scene_id:context.sceneId,base_image_id:context.baseImageId,title:context.title,instruction:context.instruction,operation:context.operation,base:context.baseLabel,target:{...context.target},dims:{...context.dimensions},status:'Preparing',rounds:[],createdAt:new Date().toISOString(),retryOf,prompt_version:prompt_snapshot.prompt_version,prompt_last_updated_at:prompt_snapshot.last_updated_at,prompt_snapshot,context:{...context,target:{...context.target},dimensions:{...context.dimensions}}};tasks.unshift(task);persistTasks();renderTaskRows();renderPipeline(task);return task}
function detectTextPositionConflict(text,point){const saysLeft=/左侧|左边|靠左|向左/.test(text),saysRight=/右侧|右边|靠右|向右/.test(text);if(point.x>=65&&saysLeft)return{suggested:{...point,x:25}};if(point.x<=35&&saysRight)return{suggested:{...point,x:75}};return null}
function assessPlacement(text,point){const floorItem=/落地灯|沙发|床|餐桌|茶几|椅子|座椅|柜|冰箱|洗衣机/.test(text),wideItem=/沙发|床|餐桌|大柜/.test(text);if(floorItem&&point.y<42)return{severity:'obvious',reason:'该物品需要落地，但当前点位于墙面中部',suggested:{x:point.x,y:68}};if(wideItem&&(point.x<16||point.x>84))return{severity:'obvious',reason:'当前区域可能无法容纳该物品',suggested:{x:Math.min(72,Math.max(28,point.x)),y:Math.max(64,point.y)}};if(floorItem&&point.y<58)return{severity:'mild',reason:'点位略高于可靠的接地区域',suggested:{x:point.x,y:62}};return null}
async function resolvePreflight(task){const context=task.context,conflict=detectTextPositionConflict(context.instruction,context.target);if(conflict){const choice=await askChoice('你选择的位置与文字描述不一致，请确认以哪一个为准。',[{label:'以点选位置为准',value:'point'},{label:'以文字描述为准',value:'text'}]);if(choice==='text')context.target={...conflict.suggested};context.positionResolution=choice==='text'?'以文字描述为准，已将落点调整到文字指定的一侧。':'以点选位置为准，忽略文字中冲突的左右方位。'}const placement=assessPlacement(context.instruction,context.target);if(placement?.severity==='mild'){context.target={...placement.suggested};context.placementResolution=`轻微偏差已自动纠正：${placement.reason}。`}else if(placement?.severity==='obvious'){const choice=await askChoice(`${placement.reason}。建议位置为 X ${placement.suggested.x}%、Y ${placement.suggested.y}%。`,[{label:'使用建议位置',value:'suggested'},{label:'仍按原位置',value:'original'}]);if(choice==='suggested')context.target={...placement.suggested};context.placementResolution=choice==='suggested'?'用户确认使用系统建议位置。':'用户确认仍按原位置。'}context.target=targetFromRatios(Number.isFinite(context.target.x_ratio)?context.target.x_ratio:context.target.x/100,Number.isFinite(context.target.y_ratio)?context.target.y_ratio:context.target.y/100);task.target={...context.target};task.status='Running';persistTasks();renderTaskRows();renderPipeline(task)}
function nextPromptVersion(){const n=Number(String(promptConfig.prompt_version||'').match(/(\d+)$/)?.[1]||1);return'prompt-v'+(n+1)}
function formatPromptTime(value){if(!value)return'—';try{return new Date(value).toLocaleString('zh-CN',{hour12:false})}catch{return String(value)}}
function renderPromptManager(editingKey=''){
  const root=$('#promptCards');if(!root)return;
  $('#promptVersion').textContent=promptConfig.prompt_version;$('#promptUpdatedAt').textContent=formatPromptTime(promptConfig.last_updated_at);
  root.innerHTML=Object.keys(DEFAULT_PROMPTS).map(key=>{const editing=editingKey===key;return`<article class="prompt-card ${editing?'editing':''}" data-prompt-key="${key}"><div class="prompt-card-head"><div><strong>${PROMPT_LABELS[key]}</strong><span>${escapeHTML(promptConfig.prompt_version)} · ${escapeHTML(formatPromptTime(promptConfig.last_updated_at))}</span></div>${editing?'<div class="prompt-actions"><button class="prompt-btn save-prompt">保存</button><button class="prompt-btn cancel-prompt">取消</button><button class="prompt-btn reset-prompt">恢复默认 Prompt</button></div>':'<button class="prompt-btn edit-prompt">编辑</button>'}</div><textarea class="prompt-editor" ${editing?'':'readonly'} aria-label="${PROMPT_LABELS[key]} Prompt">${escapeHTML(promptConfig.prompts[key])}</textarea></article>`}).join('');
  $$('.edit-prompt',root).forEach(button=>button.onclick=()=>renderPromptManager(button.closest('.prompt-card').dataset.promptKey));
  $$('.cancel-prompt',root).forEach(button=>button.onclick=()=>renderPromptManager());
  $$('.reset-prompt',root).forEach(button=>button.onclick=()=>{const card=button.closest('.prompt-card'),key=card.dataset.promptKey;$('.prompt-editor',card).value=DEFAULT_PROMPTS[key];toast('已填入默认 Prompt，点击保存后生效')});
  $$('.save-prompt',root).forEach(button=>button.onclick=()=>{const card=button.closest('.prompt-card'),key=card.dataset.promptKey,value=$('.prompt-editor',card).value.trim();if(!value)return toast('Prompt 不能为空');if(value.length>12000)return toast('Prompt 不能超过 12000 个字符');promptConfig={prompt_version:nextPromptVersion(),last_updated_at:new Date().toISOString(),prompts:{...promptConfig.prompts,[key]:value}};localStorage.setItem(PROMPT_STORAGE_KEY,JSON.stringify(promptConfig));renderPromptManager();toast(`${PROMPT_LABELS[key]} 已保存并立即生效`)})
}
function renderTaskRows(){const root=$('#taskRows');root.innerHTML=tasks.map((t,index)=>{const images=(t.rounds||[]).filter(r=>r.imageUrl).length;return`<div class="task" data-task-id="${t.id}"><strong>${index===0?'<em class="latest">最新</em> ':''}${t.id}</strong><span>${escapeHTML(t.title)}</span><span>${t.operation}</span><span>${escapeHTML(t.base)} · ${images} 张过程图</span><span class="status">${escapeHTML(t.status)}</span><button class="view-flow" data-id="${t.id}">查看真实流程</button></div>`}).join('');$$('.view-flow',root).forEach(b=>b.onclick=()=>{const t=tasks.find(x=>x.id===b.dataset.id);if(t){renderPipeline(t);$('#pipeline').scrollIntoView({behavior:'smooth'})}})}
function visualForRound(round){if(round.imageUrl)return`<div class="round-image-wrap"><img class="round-room" src="${escapeHTML(round.imageUrl)}" alt="${escapeHTML(round.name)}实际输出图"><a class="round-download" href="${escapeHTML(round.imageUrl)}" target="_blank" rel="noopener">查看 / 下载本轮</a></div>`;return`<div class="jsonbox">${escapeHTML(JSON.stringify(round.data||{},null,2))}</div>`}
function formatStageTime(value){if(!value)return'—';try{return new Date(value).toLocaleTimeString('zh-CN',{hour12:false})}catch{return String(value)}}
function renderPipeline(task){
  const elapsed=task.elapsedMs?`${(task.elapsedMs/1000).toFixed(1)}s`:'执行中',imageCount=(task.rounds||[]).filter(r=>r.imageUrl).length,taskPromptVersion=task.prompt_version||task.rounds?.find(r=>r.prompt_version)?.prompt_version||'历史版本',taskPromptTime=task.prompt_last_updated_at||task.rounds?.find(r=>r.last_updated_at)?.last_updated_at||'';
  const cards=(task.rounds||[]).map((r,i)=>`<article class="round-card r${i}"><div class="round-card-head"><span class="round-name">${escapeHTML(r.name||('Round '+i))}</span><span class="round-state">${escapeHTML(r.state||'DONE')}${Number.isFinite(r.duration)?` · ${(r.duration/1000).toFixed(1)}s`:r.durationMs?` · ${(r.durationMs/1000).toFixed(1)}s`:''}</span></div><div class="round-visual">${visualForRound(r)}</div><div class="round-body"><p>${escapeHTML(r.description||'')}</p>${r.requestId?`<p class="request-id"><strong>百炼 request_id</strong> ${escapeHTML(r.requestId)}</p>`:''}<div class="prompt-round-meta"><span>prompt_version <strong>${escapeHTML(r.prompt_version||taskPromptVersion)}</strong></span><span>last_updated_at <strong>${escapeHTML(formatPromptTime(r.last_updated_at||taskPromptTime))}</strong></span></div><div class="io-strip"><span class="io">开始<strong>${escapeHTML(formatStageTime(r.start_time))}</strong></span><span class="io">结束<strong>${escapeHTML(formatStageTime(r.end_time))}</strong></span><span class="io">耗时<strong>${Number.isFinite(r.duration)?escapeHTML((r.duration/1000).toFixed(1)+'s'):'—'}</strong></span></div><div class="io-strip"><span class="io">输入<strong>${escapeHTML(r.input||'')}</strong></span><span class="io">输出<strong>${escapeHTML(r.output||'')}</strong></span></div><details><summary>查看当时实际使用的 Prompt / 结果</summary><pre>${escapeHTML(r.prompt||JSON.stringify(r.data||{},null,2))}</pre></details></div></article>`).join('');
  $('#pipeline').innerHTML=`<div class="pipeline-head"><div><h2>${task.id} · ${escapeHTML(task.title)}</h2><p>真实链路：Round 0 需求解析 → Round 1 基础生成 → Round 2 综合修正 → Round 3 质量检查；历史任务始终保留创建时的 Prompt 快照</p></div><div class="pipeline-summary"><span class="summary-pill">Prompt ${escapeHTML(taskPromptVersion)}</span><span class="summary-pill">更新 ${escapeHTML(formatPromptTime(taskPromptTime))}</span><span class="summary-pill">主编辑图 ${escapeHTML(task.base)}</span><span class="summary-pill">落点 ${task.target?.x??'—'}%, ${task.target?.y??'—'}%</span><span class="summary-pill">后台 ${imageCount} 张过程图</span><span class="summary-pill">${elapsed}</span><span class="summary-pill">${escapeHTML(task.status)}</span></div></div><div class="round-grid">${cards||'<article class="round-card"><div class="round-body"><p>服务端正在执行。正常情况下只生成 Round 1 和 Round 2 两张后台过程图。</p></div></article>'}</div>`
}

async function asDataUrl(src){if(src.startsWith('data:'))return src;const r=await fetch(src);if(!r.ok)throw new Error('无法读取图片');const blob=await r.blob();return await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob)})}
async function imageSourceForApi(src){if(/^https:\/\//i.test(src))return src;return asDataUrl(src)}
function inspectImageSource(src,source_kind='original-file'){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve({original_width:img.naturalWidth,original_height:img.naturalHeight,aspect_ratio:img.naturalWidth/img.naturalHeight,source_kind});img.onerror=()=>reject(new Error('无法读取图片尺寸'));img.src=src})}
async function readOriginalImage(file){if(!/^image\/(png|jpeg|webp)$/i.test(file.type))throw new Error('仅支持 PNG、JPEG 或 WebP');if(file.size>10_000_000)throw new Error('空间原图超过 10MB，请先做无裁切压缩后再上传');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const meta=await inspectImageSource(src,'original-upload');return{src,meta:{...meta,file_name:file.name,file_size:file.size}}}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function callGenerationStage(action,input,retryNetwork=true){try{const response=await fetch('/api/generate-stage',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...input,action})});const payload=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(payload.error||`本轮服务返回 ${response.status}`);error.status=response.status;throw error}return payload}catch(error){const safeToRetry=['poll-image','analyze','quality'].includes(action),transient=error instanceof TypeError||[429,502,503,504].includes(error.status)||(action==='quality'&&error.status===500);if(retryNetwork&&safeToRetry&&transient){await wait(1800);return callGenerationStage(action,input,false)}throw error}}
async function waitForImageStage(action,input,task,index,shouldRecord=true){const started=Date.now(),submitted=await callGenerationStage(action,input,false);task.activeStage={action,taskId:submitted.taskId,index};persistTasks();renderTaskRows();renderPipeline(task);for(let count=0;count<150;count++){await wait(count?3500:1200);const status=await callGenerationStage('poll-image',{taskId:submitted.taskId});if(status.taskStatus==='SUCCEEDED'&&status.resultUrl){const ended=Date.now(),duration=ended-started,round={...submitted.round,state:'GENERATED',imageUrl:status.resultUrl,start_time:new Date(started).toISOString(),end_time:new Date(ended).toISOString(),duration,durationMs:duration,taskId:submitted.taskId};task.activeStage=null;if(shouldRecord)recordRound(task,round,index);return{resultUrl:status.resultUrl,round}}if(['FAILED','CANCELED','UNKNOWN'].includes(status.taskStatus))throw new Error(status.failure||`百炼任务状态为 ${status.taskStatus}`);toast(`${submitted.round.name}正在百炼后台处理…`)}throw new Error('本轮生成超过等待时间，请稍后重试')}
function updateTaskProgress(task,index,state='running'){const mutation=mutationForConversation(task.conversation_id),box=$(`.round-status[data-task-id="${task.id}"]`,mutation.root);updateProgress(box,index,state);commitConversationMutation(task,mutation)}
function recordRound(task,round,index){task.rounds.push(round);task.status='Running';task.checkpoint={nextStage:index+1,resultUrl:round.imageUrl||task.checkpoint?.resultUrl||null};persistTasks();renderTaskRows();renderPipeline(task);updateTaskProgress(task,index+1)}
function replaceRoundTwo(task,corrected){const index=task.rounds.findIndex(round=>String(round.name).startsWith('Round 2')),initial=task.rounds[index];if(index<0||!initial)return;const duration=(initial.duration||initial.durationMs||0)+(corrected.duration||corrected.durationMs||0);task.rounds[index]={...corrected,name:'Round 2 综合修正',state:'CORRECTED',description:'首次质检未通过，已执行唯一一次局部纠错；本卡片保留纠错后的 Round 2 图。',start_time:initial.start_time,end_time:corrected.end_time,duration,durationMs:duration,data:{initial_attempt:{request_id:initial.requestId,start_time:initial.start_time,end_time:initial.end_time,duration:initial.duration,prompt:initial.prompt},correction_attempt:{request_id:corrected.requestId,start_time:corrected.start_time,end_time:corrected.end_time,duration:corrected.duration,prompt:corrected.prompt}}};persistTasks();renderTaskRows();renderPipeline(task)}
function unavailableQualityRound(task,error,started,initialCheck=null){const ended=Date.now(),ownDuration=ended-started,initialDuration=initialCheck?.duration||initialCheck?.durationMs||0,snapshot=task.prompt_snapshot||defaultPromptConfig(),requestId=String(error?.message||'').match(/request_id:\s*([\w-]+)/i)?.[1]||'';return{name:'Round 3 质量检查',state:'UNAVAILABLE',description:'Round 2 已成功生成，但百炼质量检查服务暂时不可用；结果已保留并交由用户确认。',input:'原始图 + 商品图 + Round 2 图',output:'qc-unavailable.json',requestId,start_time:initialCheck?.start_time||new Date(started).toISOString(),end_time:new Date(ended).toISOString(),duration:initialDuration+ownDuration,durationMs:initialDuration+ownDuration,data:{message:error?.message||'质量检查服务暂时不可用',initial_check:initialCheck||null,retry_used:!!initialCheck},prompt:snapshot.prompts?.round3||DEFAULT_PROMPTS.round3,prompt_version:snapshot.prompt_version,last_updated_at:snapshot.last_updated_at}}
function recoverLegacyQualityFailures(){for(const task of tasks){if(task.status!=='Failed'||task.result||!task.context||(task.conversation_id!==currentChatId&&!conversations.has(task.conversation_id)))continue;const errorRound=[...(task.rounds||[])].reverse().find(round=>round.name==='错误'&&round.state==='FAILED'),round2=[...(task.rounds||[])].reverse().find(round=>String(round.name).startsWith('Round 2')&&round.imageUrl),message=errorRound?.description||'';if(!round2||!/(InternalError\.Algo\.ModelServingError|百炼接口 500)/i.test(message))continue;const mutation=mutationForConversation(task.conversation_id),retryButton=$(`.retry-task-btn[data-task-id="${task.id}"]`,mutation.root);retryButton?.closest('.message')?.remove();commitConversationMutation(task,mutation);task.rounds=task.rounds.filter(round=>round!==errorRound);const qcRound=unavailableQualityRound(task,new Error(message),Date.now());task.rounds.push(qcRound);const qc={pass:false,incomplete:true,issues:['质量检查服务暂时不可用'],error:message},attempts=2,requestIds=task.rounds.flatMap(round=>[round.requestId,round.data?.initial_attempt?.request_id,round.data?.correction_attempt?.request_id]).filter(Boolean);task.status='QC unavailable';task.completedAt=task.completedAt||new Date().toISOString();task.checkpoint=null;task.result={resultUrl:round2.imageUrl,qc,attempts,requestIds};persistTasks();deliverTaskSuccess(task,{resultUrl:round2.imageUrl,qc,attempts,rounds:task.rounds,requestIds})}}
async function resizeFile(file,maxSide=1536){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',.9))};img.src=reader.result};reader.readAsDataURL(file)})}
function deriveTitle(text){return text.replace(/^(添加|替换)[:：]?/,'').slice(0,18)||'新的生图对话'}
function currentSessionButton(){return $(`.session[data-chat="${currentChatId}"]`)}
function refreshHeader(){const messages=$$('.message',feedInner).length,images=$$('.effect-stage',feedInner).length;$('.chathead-meta').textContent=`已自动保存 · ${messages} 条消息 · ${images} 张真实生成图`;const b=currentSessionButton();if(b){const badge=$('.session-meta span:last-child',b);if(badge)badge.textContent=images?images+' 张图':'待生成'}}

async function executeTask(task){
  const context=task.context,started=performance.now();
  try{
    const [roomImage,productImage]=await Promise.all([imageSourceForApi(context.baseImageSource),imageSourceForApi(context.productImageSource)]),baseImageMeta=context.baseImageMeta?.original_width?context.baseImageMeta:await inspectImageSource(context.baseImageSource,context.baseLabel==='Original'?'original-upload':'historical-generated-original');
    context.baseImageMeta=baseImageMeta;const input={roomImage,productImage,imageMeta:{...baseImageMeta},instruction:context.instruction,operation:context.operation,target:{...context.target},dimensions:{...context.dimensions},baseLabel:context.baseLabel,positionResolution:context.positionResolution||'',placementResolution:context.placementResolution||'',taskId:task.task_id,conversationId:task.conversation_id,sceneId:task.scene_id,baseImageId:task.base_image_id,promptSnapshot:copyPromptConfig(task.prompt_snapshot||defaultPromptConfig())};
    updateTaskProgress(task,0);const analyzed=await callGenerationStage('analyze',input);const analysis=analyzed.analysis;recordRound(task,analyzed.round,0);
    updateTaskProgress(task,1);let generated=await waitForImageStage('base',{...input,analysis},task,1),resultUrl=generated.resultUrl;
    updateTaskProgress(task,2);generated=await waitForImageStage('composite',{...input,analysis,previousUrl:resultUrl},task,2);resultUrl=generated.resultUrl;
    updateTaskProgress(task,3);let quality,qc,attempts=2,initialCheck=null,qualityStarted=Date.now();
    try{quality=await callGenerationStage('quality',{...input,analysis,resultUrl});qc=quality.qc;initialCheck=quality.round}catch(qualityError){quality={round:unavailableQualityRound(task,qualityError,qualityStarted)};qc={pass:false,incomplete:true,issues:['质量检查服务暂时不可用'],error:qualityError.message}}
    if(!qc.pass&&!qc.incomplete){attempts=3;const correction=qc.correction_prompt||`修正：${(qc.issues||[]).join('；')}`;const corrected=await waitForImageStage('retry',{...input,analysis,previousUrl:resultUrl,correction},task,2,false);resultUrl=corrected.resultUrl;replaceRoundTwo(task,corrected.round);qualityStarted=Date.now();try{quality=await callGenerationStage('quality',{...input,analysis,resultUrl,isRetry:true});qc=quality.qc;const finalDuration=quality.round.duration||quality.round.durationMs||0,combinedDuration=(initialCheck.duration||initialCheck.durationMs||0)+finalDuration;quality.round.start_time=initialCheck.start_time;quality.round.duration=combinedDuration;quality.round.durationMs=combinedDuration;quality.round.data={...(quality.round.data||{}),initial_check:{request_id:initialCheck.requestId,start_time:initialCheck.start_time,end_time:initialCheck.end_time,duration:initialCheck.duration,state:initialCheck.state,issues:initialCheck.data?.issues||[]},retry_used:true}}catch(qualityError){quality={round:unavailableQualityRound(task,qualityError,qualityStarted,initialCheck)};qc={pass:false,incomplete:true,issues:['质量检查服务暂时不可用'],error:qualityError.message}}}
    recordRound(task,quality.round,3);const requestIds=task.rounds.flatMap(round=>[round.requestId,round.data?.initial_attempt?.request_id,round.data?.correction_attempt?.request_id]).filter(Boolean),payload={resultUrl,qc,attempts,rounds:task.rounds,requestIds};task.status=qc.pass?'Success':qc.incomplete?'QC unavailable':'Needs review';task.elapsedMs=Math.round(performance.now()-started);task.completedAt=new Date().toISOString();task.checkpoint=null;task.result={resultUrl,qc,attempts,requestIds};persistTasks();renderTaskRows();renderPipeline(task);
    const v=deliverTaskSuccess(task,payload);toast(v+' 已生成，已写回任务创建时的对话');
  }catch(err){task.status='Failed';task.elapsedMs=Math.round(performance.now()-started);task.rounds.push({name:'错误',state:'FAILED',description:err.message,data:{message:err.message}});persistTasks();renderTaskRows();renderPipeline(task);deliverTaskFailure(task,err.message);toast('生成失败：'+err.message)}
}
async function startTaskFromContext(context,retryOf='',skipPreflight=false){const task=newTask(context,retryOf);if(!skipPreflight)await resolvePreflight(task);else task.status='Running';addUser(context.instruction,context.baseLabel,context);addProgress(task.id);snapshotCurrent();feed.scrollTop=feed.scrollHeight;await executeTask(task)}
async function retryFailedTask(taskId){const failed=tasks.find(task=>task.id===taskId);if(!failed)return toast('未找到原失败任务');const state=conversations.get(failed.conversation_id),saved=failed.context||{},context={...saved,conversationId:failed.conversation_id,sceneId:failed.scene_id,baseImageId:failed.base_image_id,baseLabel:failed.base,operation:failed.operation,target:{...(saved.target||failed.target)},dimensions:{...(saved.dimensions||failed.dims)},instruction:failed.instruction,title:failed.title,baseImageSource:saved.baseImageSource||(failed.base==='Original'?state?.roomSrc:state?.resultImages?.[failed.base]),baseImageMeta:saved.baseImageMeta||(failed.base==='Original'?state?.roomImageMeta:state?.resultImageMeta?.[failed.base]),productImageSource:saved.productImageSource||state?.productSrc};if(!context.baseImageSource||!context.productImageSource)return toast('原任务素材不完整，无法直接重试');$('#send').disabled=true;try{await startTaskFromContext(context,failed.id,true)}finally{$('#send').disabled=false}}
async function sendMessage(){
  const text=$('#prompt').value.trim();
  if(!text)return toast('请先输入生图或调整要求');
  if(!roomSrc)return toast('请先上传一张空间照片');
  if(!productSrc)return toast('请先上传商品参考图');
  if(!target)return toast('请先在空间照片上点选目标位置');
  const btn=currentSessionButton();if(btn&&$('.session-title',btn).textContent==='新的生图对话'){const title=deriveTitle(text);$('.session-title',btn).textContent=title;$('.chathead-title').textContent=title}
  const context=captureTaskContext(text);$('#prompt').value='';$('#send').disabled=true;$('#replyBar').classList.remove('show');reference=null;
  try{await startTaskFromContext(context)}finally{$('#send').disabled=false;feed.scrollTop=feed.scrollHeight}
}
$('#send').onclick=sendMessage;$('#prompt').onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter')sendMessage()};

function ensureInputImage(){if(!roomSrc||$('.selectable-image',feedInner))return;const wrap=document.createElement('div');wrap.className='asset-message';wrap.innerHTML=`<div class="asset-kicker">本轮输入</div><div class="image-card"><div class="image-stage selectable-image" data-version="Original"><img class="room" src="${escapeHTML(roomSrc)}" alt="用户上传的空间照片"></div><div class="image-caption"><div class="image-caption-text"><strong>原始照片</strong><span>单击图片选择物体底部中心</span></div></div></div>`;feedInner.appendChild(wrap);bindInteractive(wrap)}
function setTile(kind,src){const tile=$(kind==='room'?'#spaceTile':'#productTile'),img=$(kind==='room'?'#spaceThumb':'#productThumb');tile.classList.toggle('empty',!src);if(src)img.src=src;else img.removeAttribute('src')}
$('#spaceInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const original=await readOriginalImage(f);roomSrc=original.src;roomImageMeta=original.meta;sceneId=uid('scene');baseImageId=uid('image');setTile('room',roomSrc);feedInner.innerHTML='<div class="dayline">新空间素材</div>';ensureInputImage();target=null;updateTargetUI();snapshotCurrent();toast(`空间原图已保留：${original.meta.original_width}×${original.meta.original_height}`)}catch(err){toast(err.message||'空间照片读取失败，请更换清晰的 PNG 或 JPEG 图片')}finally{e.target.value=''}};
$('#productInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;const status=$('#productStatus');status.textContent='正在优化商品参考图尺寸…';try{productSrc=await resizeFile(f);setTile('product',productSrc);status.className='product-status ok';status.textContent='商品原图已作为参考图保存 · 不会在浏览器直接抠图或叠加';snapshotCurrent();toast('商品参考图已更新')}catch{status.className='product-status error';status.textContent='商品图读取失败，请更换 PNG 或 JPEG 图片'}finally{e.target.value=''}};
$('#attachProduct').onclick=()=>$('#productInput').click();

function persistConversations(){try{localStorage.setItem(CONVERSATION_STORAGE_KEY,JSON.stringify({activeId:currentChatId,items:[...conversations.entries()].slice(0,12)}))}catch(err){console.warn('对话自动保存空间不足',err)}}
function persistDeletedConversationIds(){localStorage.setItem(DELETED_CONVERSATIONS_KEY,JSON.stringify([...deletedConversationIds]))}
function sessionMarkup(title,time,badge){return`<div class="session-title">${escapeHTML(title)}</div><div class="session-meta"><span>${escapeHTML(time)}</span><span class="session-badge">${escapeHTML(badge)}</span></div><button class="session-delete" type="button" aria-label="删除历史对话" title="删除历史对话">删除</button>`}
function ensureSessionButton(id,state){if(deletedConversationIds.has(id)||$(`.session[data-chat="${id}"]`))return;const b=document.createElement('div');b.className='session';b.dataset.chat=id;b.setAttribute('role','button');b.tabIndex=0;b.innerHTML=sessionMarkup(state.title||'历史生图对话','已保存',(state.version||0)+' 张图');$('.searchbox').after(b);bindSession(b)}
function loadConversations(){try{const saved=JSON.parse(localStorage.getItem(CONVERSATION_STORAGE_KEY)||'null');if(!saved||!Array.isArray(saved.items))return null;for(const [id,state] of saved.items){if(!id||!state||deletedConversationIds.has(id))continue;conversations.set(id,state);ensureSessionButton(id,state)}return saved.activeId&&!deletedConversationIds.has(saved.activeId)?saved.activeId:null}catch(err){console.warn('对话记录读取失败',err);return null}}
function snapshotCurrent(){if(!currentChatId)return;conversations.set(currentChatId,{title:$('.chathead-title').textContent,meta:$('.chathead-meta').textContent,feedHTML:feedInner.innerHTML,roomSrc,roomImageMeta,productSrc,version,sceneId,baseImageId,target:target?{...target}:null,operation,reference,dimensions:getDimensions(),resultImages:Object.fromEntries(resultImages),resultImageMeta:Object.fromEntries(resultImageMeta)});persistConversations()}
function archivedState(title,count){return{title,meta:`已归档 · ${count} 张效果图`,feedHTML:`<div class="dayline">已归档对话</div><div class="message"><div class="msgavatar">AI</div><div class="bubble">此历史题目来自另一段独立对话；示例数据不冒充真实生成轮次。</div></div>`,roomSrc:'',roomImageMeta:null,productSrc:'',version:count,sceneId:uid('scene'),baseImageId:uid('image'),target:null,operation:title.includes('替换')?'REPLACE':'ADD',reference:null,dimensions:{},resultImages:{},resultImageMeta:{}}}
function restoreConversation(id){if(id===currentChatId)return;snapshotCurrent();currentChatId=id;const b=$(`.session[data-chat="${id}"]`);let s=conversations.get(id);if(!s){const count=parseInt($('.session-meta span:last-child',b).textContent)||0;s=archivedState($('.session-title',b).textContent,count);conversations.set(id,s)}$('.chathead-title').textContent=s.title;$('.chathead-meta').textContent=s.meta;feedInner.innerHTML=s.feedHTML;roomSrc=s.roomSrc;roomImageMeta=s.roomImageMeta||null;productSrc=s.productSrc;version=s.version;sceneId=s.sceneId||(s.sceneId=uid('scene'));baseImageId=s.baseImageId||(s.baseImageId=uid('image'));target=s.target?{...s.target}:null;if(target&&(!Number.isFinite(target.x_ratio)||!Number.isFinite(target.y_ratio)))target=targetFromRatios(target.x/100,target.y/100);reference=s.reference;resultImages.clear();resultImageMeta.clear();Object.entries(s.resultImages||{}).forEach(([key,value])=>resultImages.set(key,value));Object.entries(s.resultImageMeta||{}).forEach(([key,value])=>resultImageMeta.set(key,value));setOperation(s.operation,true);setTile('room',roomSrc);setTile('product',productSrc);const d=s.dimensions||{};$('#dimLength').value=d.length||'';$('#dimWidth').value=d.width||'';$('#dimHeight').value=d.height||'';$('#productStatus').textContent=productSrc?'商品原图仅作为外观参考 · 不再直接抠图叠加':'等待上传商品参考图';$('#replyBar').classList.toggle('show',!!reference);updateTargetUI();updateScaleHint();$$('.session').forEach(x=>x.classList.toggle('active',x.dataset.chat===id));bindInteractive(feedInner);persistConversations();toast('已恢复自动保存的独立对话')}
function conversationHasActiveTask(id){return tasks.some(task=>task.conversation_id===id&&['Preparing','Running'].includes(task.status))}
async function requestDeleteConversation(id){
  if(conversationHasActiveTask(id))return toast('该对话仍有生成任务进行中，请等待完成后再删除。');
  const choice=await askChoice('确定删除该历史对话吗？删除后无法恢复。',[{label:'确认删除',value:'delete'},{label:'取消',value:'cancel'}]);
  if(choice!=='delete')return;
  const deletingCurrent=id===currentChatId;
  conversations.delete(id);deletedConversationIds.add(id);persistDeletedConversationIds();
  $(`.session[data-chat="${id}"]`)?.remove();
  for(let i=tasks.length-1;i>=0;i--)if(tasks[i].conversation_id===id)tasks.splice(i,1);
  persistTasks();
  if(deletingCurrent){currentChatId='';const next=$('.session');if(next)restoreConversation(next.dataset.chat);else startNewChat()}else persistConversations();
  renderTaskRows();if(!admin.classList.contains('off')){if(tasks[0])renderPipeline(tasks[0]);else $('#pipeline').innerHTML='<div class="pipeline-head"><div><h2>尚无真实生成任务</h2><p>发送第一条指令后，这里会显示各轮真实流程。</p></div></div>'}
  toast('历史对话已删除');
}
function bindSession(b){
  if(deletedConversationIds.has(b.dataset.chat)){b.remove();return}
  if(!b.hasAttribute('role')){b.setAttribute('role','button');b.tabIndex=0}
  let deleteButton=$('.session-delete',b);if(!deleteButton){deleteButton=document.createElement('button');deleteButton.type='button';deleteButton.className='session-delete';deleteButton.textContent='删除';deleteButton.setAttribute('aria-label','删除历史对话');deleteButton.title='删除历史对话';b.appendChild(deleteButton)}
  deleteButton.onclick=e=>{e.stopPropagation();requestDeleteConversation(b.dataset.chat)};
  b.onclick=e=>{if(!e.target.closest('.session-delete'))restoreConversation(b.dataset.chat)};
  b.onkeydown=e=>{if(e.target!==b)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();restoreConversation(b.dataset.chat)}}
}
$$('.session').forEach(bindSession);
function startNewChat(){snapshotCurrent();const id='chat-'+Date.now(),b=document.createElement('div');b.className='session';b.dataset.chat=id;b.setAttribute('role','button');b.tabIndex=0;b.innerHTML=sessionMarkup('新的生图对话','刚刚','待生成');$('.searchbox').after(b);bindSession(b);conversations.set(id,{title:'新的生图对话',meta:'独立对话 · 等待上传素材',feedHTML:'<div class="dayline">新对话</div><div class="message"><div class="msgavatar">AI</div><div class="bubble">这是一段全新的对话。上一段内容已经归档；请上传空间照片和商品参考图。</div></div>',roomSrc:'',roomImageMeta:null,productSrc:'',version:0,sceneId:uid('scene'),baseImageId:uid('image'),target:null,operation:'ADD',reference:null,dimensions:{},resultImages:{},resultImageMeta:{}});currentChatId='';restoreConversation(id);$('#prompt').value='';persistConversations();toast('新对话已清空，上一段已归档')}
$('#newChat').onclick=startNewChat;$('#mobileNewChat').onclick=startNewChat;
$('#sessionSearch').oninput=e=>$$('.session').forEach(s=>s.style.display=s.textContent.includes(e.target.value)?'':'none');
$('#openContext').onclick=()=>innerWidth<=800?toast('素材面板在桌面宽度下显示'):$('#context').scrollIntoView({behavior:'smooth'});
$('#refresh').onclick=()=>{promptConfig=loadPromptConfig();renderPromptManager();loadTaskHistory();renderTaskRows();if(tasks[0])renderPipeline(tasks[0]);toast('已同步最新任务、Prompt 版本和各轮图片')};

window.addEventListener('storage',e=>{if(e.key===TASK_STORAGE_KEY){loadTaskHistory();renderTaskRows();if(!admin.classList.contains('off')&&tasks[0])renderPipeline(tasks[0])}if(e.key===CONVERSATION_STORAGE_KEY&&document.visibilityState==='visible'){const savedId=loadConversations();if(savedId&&savedId!==currentChatId){currentChatId='';restoreConversation(savedId)}}});
const savedChatId=loadConversations();if(savedChatId&&conversations.has(savedChatId)){currentChatId='';restoreConversation(savedChatId)}else{const initialSession=$('.session');if(initialSession?.dataset.chat==='chat-chair'&&!deletedConversationIds.has('chat-chair'))snapshotCurrent();else if(initialSession){currentChatId='';restoreConversation(initialSession.dataset.chat)}else{currentChatId='';startNewChat()}}loadTaskHistory();recoverLegacyQualityFailures();renderPromptManager();renderTaskRows();if(tasks[0])renderPipeline(tasks[0]);bindInteractive();updateTargetUI();updateScaleHint();
